#!/usr/bin/env bash
# Generates ./.env (repo root, git-ignored) for the local stack with FRESH random secrets.
# No email provider, no social API keys, no LLM keys, no Stripe. Refuses to overwrite unless --force.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
OUT="$ROOT/.env"
[[ -e "$OUT" && "${1:-}" != "--force" ]] && { echo ".env exists (use --force to regenerate)"; exit 0; }
cat > "$OUT" <<ENV
# generated by neptive/dev/make-env.sh -- LOCAL ONLY, never commit
DATABASE_URL="postgresql://postiz-app:pzn-local-only@127.0.0.1:55432/postiz-db"
REDIS_URL="redis://127.0.0.1:56379"
TEMPORAL_ADDRESS="127.0.0.1:57233"
JWT_SECRET="$(openssl rand -hex 32)"
FRONTEND_URL="http://localhost:4200"
MAIN_URL="http://localhost:4200"
NEXT_PUBLIC_BACKEND_URL="http://localhost:3000"
BACKEND_INTERNAL_URL="http://localhost:3000"
NOT_SECURED="true"
IS_GENERAL="true"
DISABLE_REGISTRATION="true"
STORAGE_PROVIDER="local"
UPLOAD_DIRECTORY="$ROOT/neptive/dev/.data/uploads"
NEXT_PUBLIC_UPLOAD_DIRECTORY="/uploads"
NX_ADD_PLUGINS=false
ENV
mkdir -p "$ROOT/neptive/dev/.data/uploads"
echo "wrote $OUT"
